public boolean isRatePresentOnFileMap(Map<String, String> fileRoeMap, String currency) {
    if (currency == null || currency.isEmpty() || fileRoeMap == null || fileRoeMap.isEmpty()) {
        return false;
    }

    for (String fileRoeCurrency : fileRoeMap.keySet()) {
        if (fileRoeCurrency != null && fileRoeCurrency.equalsIgnoreCase(currency)) {
            return true;
        }
    }

    return false;
}

Notes:
