["Here's a compact SwiftUI example that displays your Task model in a list, shows completion state, and formats the completion date.

```swift
import SwiftUI

struct Task: Codable, Identifiable {
    let id: Int
    let description: String
    let completedAt: Date?
}

struct TaskRow: View {
    let task: Task

    var body: some View {
        HStack {
            Image(systemName: task.completedAt != nil ? "checkmark.circle.fill" : "circle")
                .foregroundColor(task.completedAt != nil ? .green : .secondary)
            VStack(alignment: .leading) {
                Text(task.description)
                    .font(.headline)
                if let completed = task.completedAt {
                    Text("Completed " + DateFormatter.task.string(from: completed))
                        .font(.caption)
                        .foregroundColor(.secondary)
                } else {
                    Text("Not completed")
                        .font(.caption)
                        .foregroundColor(.secondary)
                }
            }
            Spacer()
            Text("#\(task.id)")
                .font(.caption)
                .foregroundColor(.secondary)
        }
        .padding(.vertical, 4)
    }
}

extension DateFormatter {
    static let task: DateFormatter = {
        let df = DateFormatter()
        df.dateStyle = .medium
        df.timeStyle = .short
        return df
    }()
}

struct TaskList: View {
    @State private var tasks: [Task] = [
        Task(id: 1, description: "Buy groceries", completedAt: nil),
        Task(id: 2, description: "Write report", completedAt: Date().addingTimeInterval(-3600*24))
    ]

    var body: some View {
        NavigationView {
            List(tasks) { task in
                TaskRow(task: task)
            }
            .navigationTitle("Tasks")
        }
    }
}

struct TaskList_Previews: PreviewProvider {
    static var previews: some View {
        TaskList()
    }
}
```

Notes:
- I made Task conform to Identifiable so it can be used directly in a List/ForEach.
- The view is read-only; to allow editing/completing tasks, you would use a mutable model (var) or a separate view model to handle updates."]

