src/main.rs:

use eframe::{egui, run_native, App, NativeOptions};

struct SearchApp {
    search: String,
    items: Vec<String>,
}

impl Default for SearchApp {
    fn default() -> Self {
        Self {
            search: String::new(),
            items: vec![
                "Apple".into(),
                "Banana".into(),
                "Cherry".into(),
                "Durian".into(),
                "Elderberry".into(),
                "Fig".into(),
                "Grape".into(),
            ],
        }
    }
}

impl App for SearchApp {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        egui::CentralPanel::default().show(ctx, |ui| {
            ui.horizontal(|ui| {
                ui.label("Search:");
                ui.text_edit_singleline(&mut self.search);
            });

            ui.separator();

            let query = self.search.to_lowercase();

            egui::ScrollArea::vertical().max_height(400.0).show(ui, |ui| {
                for item in self
                    .items
                    .iter()
                    .filter(|it| it.to_lowercase().contains(&query))
                {
                    ui.label(item);
                }
            });
        });
    }
}

fn main() {
    let options = NativeOptions::default();
    run_native(
        "Searchable List",
        options,
        Box::new(|_cc| Box::new(SearchApp::default())),
    )
    .unwrap();
}

