Notes: you need GTK4 installed on your system and the gtk4 crate in Cargo.toml (e.g. add gtk4 = "^0.4" or a current gtk4-rs version).

```rust
use gtk::prelude::*;
use gtk::{Application, ApplicationWindow, Box as GtkBox, Entry, Label, ListBox, ListBoxRow, Orientation};
use std::rc::Rc;

fn main() {
    let app = Application::builder()
        .application_id("com.example.searchable_list")
        .build();

    app.connect_activate(build_ui);
    app.run();
}

fn build_ui(app: &Application) {
    let window = ApplicationWindow::builder()
        .application(app)
        .title("Searchable List")
        .default_width(400)
        .default_height(300)
        .build();

    let vbox = GtkBox::new(Orientation::Vertical, 8);

    let entry = Entry::new();
    entry.set_placeholder_text(Some("Type to filter..."));
    vbox.append(&entry);

    let listbox = ListBox::new();
    vbox.append(&listbox);

    // Original items stored in an Rc so closures can capture them.
    let items = Rc::new(vec![
        "Apple".to_string(),
        "Banana".to_string(),
        "Cherry".to_string(),
        "Durian".to_string(),
        "Elderberry".to_string(),
        "Fig".to_string(),
    ]);

    // Helper to (re)populate the listbox from a slice of item strings
    let populate = |listbox: &ListBox, items_iter: impl IntoIterator<Item = String>| {
        // Remove existing children
        for child in listbox.children() {
            listbox.remove(&child);
        }
        // Append matching rows
        for item in items_iter {
            let row = ListBoxRow::new();
            let label = Label::new(Some(&item));
            label.set_xalign(0.0);
            row.set_child(Some(&label));
            listbox.append(&row);
        }
    };

    // Initial populate with all items
    populate(&listbox, items.iter().cloned());

    // Connect entry changed to filter and repopulate
    {
        let listbox = listbox.clone();
        let items = items.clone();
        entry.connect_changed(move |e| {
            let filter = e.text().to_string().to_lowercase();
            if filter.is_empty() {
                populate(&listbox, items.iter().cloned());
            } else {
                let filtered = items
                    .iter()
                    .filter(|s| s.to_lowercase().contains(&filter))
                    .cloned();
                populate(&listbox, filtered);
            }
        });
    }

    window.set_child(Some(&vbox));
    window.present();
}
```

