["Here's a simple correct implementation that finds the join point by advancing the smaller current value until both are equal:

def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def next_num(n):
    return n + sum_digits(n)

def compute_join_point(s1, s2):
    s1 = int(s1)
    s2 = int(s2)
    if not (0 < s1 < 20000000 and 0 < s2 < 20000000):
        raise ValueError('s1 and s2 must be in (0, 20000000)')
    while s1 != s2:
        if s1 < s2:
            s1 = next_num(s1)
        else:
            s2 = next_num(s2)
    return s1

# Test
if __name__ == '__main__':
    def test_compute_join_point_success():
        s1 = 471
        s2 = 480
        expected_result = 519
        print(compute_join_point(s1, s2))
        assert compute_join_point(s1, s2) == expected_result
    test_compute_join_point_success()"]

