["", "Here's a concise Python implementation using the standard characterization of practical numbers: if n = ∏ p_i^{a_i} with primes p_1 < p_2 < ... then n is practical iff p_1 = 2 and for k >= 2, p_k <= 1 + sigma(∏_{i<k} p_i^{a_i}) (where sigma is the sum-of-divisors function). This runs easily for n up to 10,000.

```python
# Check practical numbers up to 10000 and verify the sum is 6,804,107

def primes_upto(n):
    sieve = [True] * (n + 1)
    primes = []
    for i in range(2, n + 1):
        if sieve[i]:
            primes.append(i)
            if i * i <= n:
                for j in range(i * i, n + 1, i):
                    sieve[j] = False
    return primes


def factorize(n, primes):
    res = []
    temp = n
    for p in primes:
        if p * p > temp:
            break
        if temp % p == 0:
            cnt = 0
            while temp % p == 0:
                temp //= p
                cnt += 1
            res.append((p, cnt))
    if temp > 1:
        res.append((temp, 1))
    return res


def is_practical(n, primes):
    if n == 1:
        return True
    fac = factorize(n, primes)
    # first prime must be 2
    if not fac or fac[0][0] != 2:
        return False
    current_sigma = 1  # sigma of the product of previous prime-power factors
    for i, (p, a) in enumerate(fac):
        if i > 0:
            # Stewart's condition: p_k <= 1 + sigma(previous part)
            if p > current_sigma + 1:
                return False
        # multiply by sigma(p^a) = (p^(a+1)-1)/(p-1)
        sigma_p = (p ** (a + 1) - 1) // (p - 1)
        current_sigma *= sigma_p
    return True


if __name__ == '__main__':
    LIMIT = 10000
    primes = primes_upto(LIMIT)
    practicals = [n for n in range(1, LIMIT + 1) if is_practical(n, primes)]
    total = sum(practicals)
    print('Count of practicals <=', LIMIT, ':', len(practicals))
    print('Sum of practicals <=', LIMIT, ':', total)
    print('Matches expected 6,804,107?', total == 6804107)

    # Quick examples
    print('12 is practical?', is_practical(12, primes))
    print('10 is practical?', is_practical(10, primes))
```

Run this script; it will print the sum and whether it matches 6,804,107."]

