          con.classList.remove('error');
          errorNote.classList.remove('show');
        }
      }

      function setDisabledState(on){
        disabled = !!on;
        if(on){
          con.classList.add('disabled');
          input.setAttribute('disabled','');
          suggestionsEl.classList.remove('show');
        } else {
          con.classList.remove('disabled');
          input.removeAttribute('disabled');
        }
      }

      // Blinking caret position update when active & empty
      function updateCaret(){
        const isActive = con.classList.contains('active');
        if(isActive && input.value.length === 0 && !disabled){
          // compute position: left padding + svg width + gap (approx)
          caret.style.display = 'block';
          // place caret left at about 72px relative to container's left (fine for demo)
          // for robust placement you'd compute text metrics — kept simple here
        } else caret.style.display = 'none';
      }

      // Show suggestions list, fills DOM
      function showSuggestions(list){
        suggestions = list || [];
        selectedIndex = -1;
        suggestionsEl.innerHTML = '';
        if(!suggestions || suggestions.length === 0) { suggestionsEl.classList.remove('show'); return; }
        suggestions.forEach((s, i)=>{
          const li = document.createElement('li');
          li.textContent = s;
          li.setAttribute('role','option');
          li.addEventListener('mousedown', (ev)=>{ // mousedown to prevent blur race
            ev.preventDefault();
            applySuggestion(i);
          });
          suggestionsEl.appendChild(li);
        });
        suggestionsEl.classList.add('show');
      }

      function applySuggestion(i){
        if(i>=0 && i < suggestions.length){
          input.value = suggestions[i];
          performSearch();
        }
      }

      // Perform search by navigating to Google search in new tab
      function performSearch(){
        const q = input.value.trim();
        if(!q) return;
        if(containsBanned(q)){
          setErrorState(true);
          suggestionsEl.classList.remove('show');
          return;
        }
        // open google search in new tab
        const url = 'https://www.google.com/search?q=' + encodeURIComponent(q);
        window.open(url, '_blank');
      }

      // JSONP fetch suggestions from Google Suggest, with fallback
      function fetchSuggestions(query, timeout=2500){
        return new Promise((resolve)=>{
          // Quick local fallback if query empty
          if(!query) return resolve([]);

          // If blocked by simulate error (testing), resolve empty
          if(chkError.checked){ return resolve([]); }

          // JSONP pattern
          const cbName = '__gsuggest_cb_' + Date.now() + '_' + Math.floor(Math.random()*1000);
          const script = document.createElement('script');
          window[cbName] = function(data){
            cleanup();
            try{
              // data format: [originalQuery, [suggestions...], ...]
              const list = (data && data[1]) ? data[1].slice(0,8) : [];
              resolve(list.length ? list : suggestionsFallback);
            }catch(e){ resolve(suggestionsFallback); }
          }
          function cleanup(){
            delete window[cbName];
            if(script.parentNode) script.parentNode.removeChild(script);
            clearTimeout(timer);
          }
          script.src = 'https://suggestqueries.google.com/complete/search?client=firefox&q=' + encodeURIComponent(query) + '&callback=' + cbName;
          script.onerror = function(){ cleanup(); resolve(suggestionsFallback); };
          document.body.appendChild(script);
          const timer = setTimeout(()=>{ cleanup(); resolve(suggestionsFallback); }, timeout);
        });
      }

      // Event bindings
      input.addEventListener('focus', ()=>{ con.classList.add('active'); setErrorState(false); updateCaret(); });
      input.addEventListener('blur', ()=>{
        // small timeout to allow mousedown handlers on suggestions
        setTimeout(()=>{ con.classList.remove('active'); suggestionsEl.classList.remove('show'); updateCaret(); }, 160);
      });

      input.addEventListener('input', async ()=>{
        setErrorState(false);
        updateCaret();
        const q = input.value.trim();
        lastQuery = q;
        if(containsBanned(q)){
          // block and show error
          setErrorState(true);
          suggestionsEl.classList.remove('show');
          return;
        }
        // fetch suggestions
        try{
          const list = await fetchSuggestions(q);
          // if user typed more since request started, ignore old results
          if(normalize(input.value) !== normalize(q)) return;
          showSuggestions(list);
        }catch(e){ showSuggestions(suggestionsFallback); }
      });

      // keyboard navigation
      input.addEventListener('keydown',(ev)=>{
        if(ev.key === 'ArrowDown' || ev.key === 'ArrowUp'){
          const items = Array.from(suggestionsEl.children);
          if(items.length === 0) return;
          ev.preventDefault();
          if(ev.key === 'ArrowDown') selectedIndex = Math.min(selectedIndex + 1, items.length - 1);
          else selectedIndex = Math.max(selectedIndex - 1, 0);
          items.forEach((it, idx)=> it.classList.toggle('active', idx === selectedIndex));
          if(selectedIndex >= 0) input.value = items[selectedIndex].textContent;
        } else if(ev.key === 'Enter'){
          ev.preventDefault();
          performSearch();
        } else if(ev.key === 'Escape'){
          suggestionsEl.classList.remove('show');
        }
      });

      btn.addEventListener('click', ()=>{ performSearch(); });

      // control toggles for demo
      chkDisabled.addEventListener('change',(e)=>{ setDisabledState(e.target.checked); });
      chkError.addEventListener('change',(e)=>{ setErrorState(e.target.checked); });

      // initial state
      setDisabledState(false);
      setErrorState(false);
      updateCaret();

      // click outside suggestion list closes it (already handled by blur) — additional safety
      document.addEventListener('click',(e)=>{ if(!con.contains(e.target)) suggestionsEl.classList.remove('show'); });

      // Accessibility note: role attributes added, keyboard nav implemented.

    })();
  </script>

</body>
</html>

----- COPY END -----

How to test
- Copy the full file above into a single index.html and open it in your browser, or paste the HTML content into CodePen/JSFiddle (HTML panel). The CSS and JS are inline so no additional files are required.
- Try typing. The caret appears when clicked; when typing, live suggestions appear (Google Suggest via JSONP, with local fallback if blocked). Press Enter or click "Go" to open Google results in a new tab.
- Toggle "Disable" to test the disabled state. Toggle "Simulate error" or type flagged words (sample list: porn, xxx, adult, sex) to see the error state.

Customization notes
- Replace or extend bannedTerms with your own policy list (consider server-side filtering for production).
- If you need to use an official Google API for suggestions, use the appropriate Google Places/Autocomplete or a custom server-side proxy with your API key.

If you want, I can:
- Separate the HTML/CSS/JS into three independent files.
- Replace JSONP suggestion fetching with a server-side proxy example or an official API integration.
- Add animations or adjust the Web3 aesthetic further (colors, gradients, glass blur strength).

Which of these would you like next?"]

