["Here's a high-performance React Native list component (TypeScript) that reads the nonprofits state from your Redux slice and uses FlatList + memoized item components, memoized selectors, and common FlatList tuning for performance. Replace RootState with your app's root state type and adapt navigation/dispatch as needed.

```tsx
import React, {useCallback, memo} from 'react';
import {View, Text, FlatList, TouchableOpacity, StyleSheet, ListRenderItemInfo} from 'react-native';
import {useSelector, useDispatch, shallowEqual} from 'react-redux';
import {createSelector} from 'reselect';
import type {NonProfit} from '../types/NonProfits';

// Replace with your real RootState type
type RootState = any;

// Fixed row height helps FlatList virtualization (must match styles.item height)
const ITEM_HEIGHT = 72;

// Selector: derive display data (mark eligible) with reselect to avoid recomputation
const selectNonProfits = (s: RootState) => s.nonprofits.nprofits as NonProfit[];
const selectEligible = (s: RootState) => s.nonprofits.eligible_nprofits as NonProfit[];

const selectDisplayNonProfits = createSelector(
  [selectNonProfits, selectEligible],
  (nprofits, eligible) => {
    const eligibleIds = new Set(eligible.map(e => e.id));
    return nprofits.map(np => ({...np, isEligible: eligibleIds.has(np.id)}));
  }
);

type DisplayNP = NonProfit & {isEligible?: boolean};

const NPItem = memo(
  ({item, onPress}: {item: DisplayNP; onPress: (id: string) => void}) => {
    return (
      <TouchableOpacity style={styles.item} onPress={() => onPress(item.id)} activeOpacity={0.7}>
        <View style={styles.row}>
          <Text numberOfLines={1} style={styles.title}>{item.name}</Text>
          {item.isEligible ? <Text style={styles.badge}>Eligible</Text> : null}
        </View>
        {item.description ? <Text numberOfLines={2} style={styles.subtitle}>{item.description}</Text> : null}
      </TouchableOpacity>
    );
  },
  // custom comparator: only re-render when relevant display fields change
  (prev, next) => prev.item.id === next.item.id
    && prev.item.isEligible === next.item.isEligible
    && prev.item.name === next.item.name
    && prev.item.description === next.item.description
);

export default function NonProfitList() {
  const dispatch = useDispatch();

  // useSelector with memoized selector and shallowEqual where appropriate
  const data = useSelector(selectDisplayNonProfits, shallowEqual) as DisplayNP[];

  // stable press handler
  const handlePress = useCallback((id: string) => {
    // e.g. navigation or dispatch an action
    // dispatch(navigateToNonProfit(id));
    console.log('pressed', id);
  }, [dispatch]);

  const renderItem = useCallback(({item}: ListRenderItemInfo<DisplayNP>) => (
    <NPItem item={item} onPress={handlePress} />
  ), [handlePress]);

  const keyExtractor = useCallback((item: DisplayNP) => item.id, []);

  const getItemLayout = useCallback((_data: DisplayNP[] | null, index: number) => ({
    length: ITEM_HEIGHT,
    offset: ITEM_HEIGHT * index,
    index,
  }), []);

  return (
    <FlatList
      data={data}
      renderItem={renderItem}
      keyExtractor={keyExtractor}
      getItemLayout={getItemLayout}
      initialNumToRender={10}
      maxToRenderPerBatch={10}
      windowSize={21}
      removeClippedSubviews={true}
      updateCellsBatchingPeriod={50}
      showsVerticalScrollIndicator={false}
      contentContainerStyle={styles.container}
    />
  );
}

const styles = StyleSheet.create({
  container: {
    paddingVertical: 8,
  },
  item: {
    height: ITEM_HEIGHT,
    paddingHorizontal: 16,
    justifyContent: 'center',
    backgroundColor: 'white',
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: '#e6e6e6',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  title: {
    fontSize: 16,
    fontWeight: '600',
    flex: 1,
  },
  subtitle: {
    marginTop: 4,
    color: '#666',
    fontSize: 13,
  },
  badge: {
    marginLeft: 8,
    paddingHorizontal: 8,
    paddingVertical: 4,
    borderRadius: 12,
    backgroundColor: '#e6f7ff',
    color: '#007aff',
    fontSize: 12,
  },
});
```

Performance notes (brief):
- Use a memoized selector (reselect) so list re-renders only when underlying arrays change.
- Memoize item components with a focused comparator so only modified rows re-render.
- Provide getItemLayout + fixed item height to let FlatList skip measurement cost.
- Tune FlatList props (initialNumToRender, maxToRenderPerBatch, windowSize) to match expected list size and device/UX.
- Avoid inline functions/objects in render path (useCallback/useMemo).
