["Below is a complete Terraform example that creates an internet-facing Application Load Balancer (ALB) with HTTP (80) and HTTPS (443) listeners, a target group, a launch template that installs nginx, and an Auto Scaling Group sized to 2 instances. Replace the variable values (VPC/subnets, certificate ARN, key pair, and allowed SSH CIDR) as needed.

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" { default = "us-east-1" }
variable "vpc_id" {}
variable "subnet_ids" { type = list(string) }
variable "key_name" { default = "my-key" }
variable "cert_arn" { default = "" } # Leave empty if you don't want HTTPS listener or provide a cert ARN
variable "allowed_ssh_cidr" { default = "0.0.0.0/0" }
variable "desired_capacity" { default = 2 }

# Security group for the ALB
resource "aws_security_group" "alb_sg" {
  name   = "alb-sg"
  vpc_id = var.vpc_id

  ingress {
    description = "HTTP"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Security group for instances - only allow traffic from ALB on 80/443
resource "aws_security_group" "instance_sg" {
  name   = "instance-sg"
  vpc_id = var.vpc_id

  ingress {
    description = "Allow traffic from ALB"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb_sg.id]
  }

  ingress {
    description = "Allow traffic from ALB (https forwarded to 80)"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.alb_sg.id]
  }

  # Optional: allow SSH
  ingress {
    description = "SSH"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ssh_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Find a recent Amazon Linux 2 AMI
data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-ebs"]
  }
}

# ALB
resource "aws_lb" "web_alb" {
  name               = "web-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = var.subnet_ids
}

# Target group (instances listen on port 80)
resource "aws_lb_target_group" "web_tg" {
  name     = "web-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = var.vpc_id

  health_check {
    path                = "/"
    matcher             = "200-399"
    interval            = 30
    unhealthy_threshold = 2
    healthy_threshold   = 2
    timeout             = 5
  }
}

# HTTP listener
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.web_alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.web_tg.arn
  }
}

# HTTPS listener (only created if cert_arn provided)
resource "aws_lb_listener" "https" {
  count             = var.cert_arn == "" ? 0 : 1
  load_balancer_arn = aws_lb.web_alb.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-2016-08"

  certificate_arn = var.cert_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.web_tg.arn
  }
}

# Launch template installs nginx and serves a simple page
resource "aws_launch_template" "web_lt" {
  name_prefix   = "web-lt-"
  image_id      = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.micro"
  key_name      = var.key_name

  network_interfaces {
    security_groups = [aws_security_group.instance_sg.id]
    associate_public_ip_address = true
  }

  user_data = base64encode(<<-EOF
              #!/bin/bash
              yum update -y
              yum install -y nginx
              systemctl enable nginx
              cat > /usr/share/nginx/html/index.html <<HTML
              <html><body><h1>Hello from Terraform ASG instance</h1></body></html>
              HTML
              systemctl start nginx
              EOF
  )
}

# Auto Scaling Group sized to two instances; registers with target group
resource "aws_autoscaling_group" "web_asg" {
  name                      = "web-asg"
  desired_capacity          = var.desired_capacity
  min_size                  = var.desired_capacity
  max_size                  = var.desired_capacity
  vpc_zone_identifier       = var.subnet_ids
  launch_template {
    id      = aws_launch_template.web_lt.id
    version = "$Latest"
  }

  target_group_arns = [aws_lb_target_group.web_tg.arn]

  health_check_type         = "ELB"
  health_check_grace_period = 60

  tag {
    key                 = "Name"
    value               = "web-asg-instance"
    propagate_at_launch = true
  }
}

# Outputs
output "alb_dns_name" {
  value = aws_lb.web_alb.dns_name
}

output "asg_name" {
  value = aws_autoscaling_group.web_asg.name
}
```

Notes:
- Provide var.vpc_id and var.subnet_ids (a list of public subnets in that VPC). The ALB must be in public subnets.
- For HTTPS, set var.cert_arn to a valid ACM certificate ARN in the same region. If cert_arn is empty, only the HTTP listener will be created.
- Adjust instance_type, AMI selection, and user_data as needed.

How to use:
1) Put this in main.tf and set the variables (via terraform.tfvars or -var). 2) terraform init && terraform apply.

If you want, I can adapt this to use a Launch Configuration instead of a Launch Template, or add an HTTPS redirect (80 -> 443) and an example ACM certificate creation."]

