    { name: 'Place C', address: '789 Oak St', lat: 37.7649, lng: -122.4294 }
  ];

  function handleRowClicked(params) {
    const { lat, lng, name, address } = params.data;
    if (lat == null || lng == null) return;

    // center map and zoom
    map.flyTo({ center: [lng, lat], zoom: 14 });

    // remove previous marker
    if (marker) marker.remove();

    // create new marker with popup
    const popup = new mapboxgl.Popup({ offset: 12 })
      .setHTML(`<strong>${escapeHtml(name)}</strong><div>${escapeHtml(address)}</div>`);

    marker = new mapboxgl.Marker()
      .setLngLat([lng, lat])
      .setPopup(popup)
      .addTo(map);

    // open popup immediately
    marker.togglePopup();
  }

  // simple HTML escape for inserted strings
  function escapeHtml(str = '') {
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  onMount(() => {
