/* Links */
a { color: var(--color-primary); }
a:visited { color: #0a5a99; }

/* Footer */
.site-footer {
  margin-top: 28px;
  padding: 18px 0;
  background: transparent;
  color: var(--color-muted);
  font-size: 0.9rem;
  text-align: center;
}

/* Small utilities */
.kicker { text-transform: uppercase; color: var(--color-muted); font-size: 0.75rem; font-weight: 700; }
.tag { background: rgba(255,166,0,0.12); color: var(--color-accent); padding: 4px 8px; border-radius: 999px; font-weight: 700; font-size: 0.8rem; }

/* Responsive */
@media (max-width: 900px) {
  .main { grid-template-columns: 1fr; }
  .article-card { grid-template-columns: 1fr; }
  .article-card .thumb { height: 160px; }
  .logo { font-size: 1.05rem; }
  .search-input { width: 140px; }
}

@media (max-width: 480px) {
  .container { padding: 12px; }
  .main-nav ul { gap: 10px; }
  .site-header .container { padding: 10px 6px; }
}

