    /* Sidebar cards */
    .sidebar .card { margin-bottom: 16px; }
    .subscribe-btn { background: var(--accent); color: var(--white); border: none; padding: 8px 12px; border-radius: 6px; font-weight: 700; cursor: pointer; }

