["Below is a small, practical C library for the Raspberry Pi Pico (Pico SDK) to communicate with a JDY-41 BLE module over UART. It provides initialization, sending AT commands, raw transmit, and a blocking read-with-timeout. Included: header (jdy41.h), implementation (jdy41.c), and an example main. Build with the Pico SDK (link against pico_stdlib and hardware_uart).

jdy41.h

```c
#ifndef JDY41_H
#define JDY41_H

#include <stdbool.h>
#include <stdint.h>
#include <stddef.h>
#include "hardware/uart.h"

// Initialize JDY-41 UART interface.
// uart_instance: uart0 or uart1
// tx_pin / rx_pin: GPIO pin numbers used for TX/RX
// baudrate: e.g. 9600
// Returns true on success.
bool jdy41_init(uart_inst_t *uart_instance, uint tx_pin, uint rx_pin, uint baudrate);

// Send a raw byte buffer over UART. Returns number of bytes written.
int jdy41_write(const uint8_t *data, size_t len);

// Send an AT command (automatically appends CRLF). Returns number of bytes written.
int jdy41_send_at(const char *cmd);

// Read into buf up to bufsize-1 bytes or until timeout_ms elapses. Null-terminates buf.
// Returns number of bytes placed into buf (not counting terminating NUL).
int jdy41_read(char *buf, size_t bufsize, uint32_t timeout_ms);

// Convenience: send AT command and wait for response into respbuf.
int jdy41_send_at_wait_response(const char *cmd, char *respbuf, size_t respbuf_size, uint32_t timeout_ms);

#endif // JDY41_H
```

jdy41.c

```c
#include "jdy41.h"
#include <string.h>
#include "pico/stdlib.h"
#include "hardware/gpio.h"
#include "hardware/uart.h"

static uart_inst_t *jdy_uart = NULL;

bool jdy41_init(uart_inst_t *uart_instance, uint tx_pin, uint rx_pin, uint baudrate) {
    if (!uart_instance) return false;
    jdy_uart = uart_instance;

    // Initialize UART hardware
    uart_init(jdy_uart, baudrate);
    gpio_set_function(tx_pin, GPIO_FUNC_UART);
    gpio_set_function(rx_pin, GPIO_FUNC_UART);

    // 8N1, no flow control
    uart_set_format(jdy_uart, 8, 1, UART_PARITY_NONE);
    uart_set_hw_flow(jdy_uart, false, false);
    uart_set_fifo_enabled(jdy_uart, true);

    return true;
}

int jdy41_write(const uint8_t *data, size_t len) {
    if (!jdy_uart || !data || len == 0) return 0;
    // uart_write_blocking returns number of bytes written
    return uart_write_blocking(jdy_uart, data, len);
}

int jdy41_send_at(const char *cmd) {
    if (!jdy_uart || !cmd) return 0;
    size_t cmdlen = strlen(cmd);
    // We'll send cmd + "\r\n"
    int written = uart_write_blocking(jdy_uart, (const uint8_t *)cmd, cmdlen);
    if (written < 0) return written;
    const char crlf[] = "\r\n";
    written += uart_write_blocking(jdy_uart, (const uint8_t *)crlf, 2);
    return written;
}

int jdy41_read(char *buf, size_t bufsize, uint32_t timeout_ms) {
    if (!jdy_uart || !buf || bufsize == 0) return 0;
    size_t idx = 0;
    uint32_t start_ms = to_ms_since_boot(get_absolute_time());

    while ((to_ms_since_boot(get_absolute_time()) - start_ms) < timeout_ms) {
        if (uart_is_readable(jdy_uart)) {
            int c = uart_getc(jdy_uart); // returns int
            if (c < 0) continue;
            if (idx + 1 < bufsize) {
                buf[idx++] = (char)c;
            }
            // Optionally, stop on newline (uncomment next lines if desired)
            // if (c == '\n') break;
        } else {
            // small sleep to avoid busy-spin
            sleep_ms(1);
        }
    }
    buf[idx] = '\0';
    return (int)idx;
}

int jdy41_send_at_wait_response(const char *cmd, char *respbuf, size_t respbuf_size, uint32_t timeout_ms) {
    int w = jdy41_send_at(cmd);
    if (w <= 0) return w;
    return jdy41_read(respbuf, respbuf_size, timeout_ms);
}
```

Example usage (main.c)

```c
#include "pico/stdlib.h"
#include <stdio.h>
#include "jdy41.h"

int main(void) {
    stdio_init_all();
    sleep_ms(500); // wait for USB serial to enumerate

    // Configure pins and UART instance for your board wiring
    const uint TX_PIN = 0; // change to the GPIO connected to JDY-41 RX
    const uint RX_PIN = 1; // change to the GPIO connected to JDY-41 TX

    // Initialize JDY-41 on uart0, 9600 bps
    if (!jdy41_init(uart0, TX_PIN, RX_PIN, 9600)) {
        printf("JDY-41 init failed\n");
        return 1;
    }

    // Send AT and wait for response
    char resp[256];
    int n = jdy41_send_at_wait_response("AT", resp, sizeof(resp), 500);
    if (n > 0) {
        printf("Response (%d): %s\n", n, resp);
    } else {
        printf("No response or error\n");
    }

    // Example of sending raw data
    const char *payload = "Hello Module";
    jdy41_write((const uint8_t *)payload, strlen(payload));

    while (true) {
        // poll for asynchronous responses
        char buf[128];
        int r = jdy41_read(buf, sizeof(buf), 200);
        if (r > 0) printf("Async: %s\n", buf);
        sleep_ms(1000);
    }

    return 0;
}
```

Build notes (CMake / Pico SDK):
- Add jdy41.c and main.c to your CMakeLists.txt
- Link against pico_stdlib and hardware_uart
- Example target link lines:
  target_sources(my_target PRIVATE jdy41.c main.c)
  target_link_libraries(my_target pico_stdlib hardware_uart)

Notes and tips:
- Wire TX/RX correctly: Pico TX -> JDY RX, Pico RX -> JDY TX.
- JDY-41 default baud is commonly 9600 but confirm with your module.
- This library is intentionally small and synchronous. For higher throughput or non-blocking behavior, adapt to use IRQ handlers or DMA.

If you want, I can: provide a non-blocking (IRQ-based) version, add parsing helpers for JDY-41 specific AT responses, or produce a CMakeLists example.", "Below is a small, portable C library for the Raspberry Pi Pico to talk to a JDY-41 (or any AT-style UART) module. It provides UART init/deinit, sending AT commands, and reading responses with timeout. It intentionally exposes a generic AT-command API — use the JDY-41-specific AT strings from its datasheet with these helpers.

```c
// jdy41.c -- simple JDY-41 UART / AT-command helper for Pico

#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include "pico/stdlib.h"
#include "hardware/uart.h"
#include "hardware/gpio.h"
#include "pico/time.h"

// Default pins for UART0 on Pico (change if you use different pins)
#ifndef JDY41_UART_ID
#define JDY41_UART_ID uart0
#endif
#ifndef JDY41_TX_PIN
#define JDY41_TX_PIN 0
#endif
#ifndef JDY41_RX_PIN
#define JDY41_RX_PIN 1
#endif
#ifndef JDY41_BAUD
#define JDY41_BAUD 9600
#endif

#define JDY41_RX_BUF_SIZE 256

static uart_inst_t *jdy_uart = JDY41_UART_ID;
static uint jdy_tx_pin = JDY41_TX_PIN;
static uint jdy_rx_pin = JDY41_RX_PIN;
static uint32_t jdy_baud = JDY41_BAUD;

// Initialize UART for JDY-41
bool jdy41_init(uint tx_pin, uint rx_pin, uint32_t baud) {
    jdy_tx_pin = tx_pin;
    jdy_rx_pin = rx_pin;
    jdy_baud = baud;

    uart_init(jdy_uart, jdy_baud);
    gpio_set_function(jdy_tx_pin, GPIO_FUNC_UART);
    gpio_set_function(jdy_rx_pin, GPIO_FUNC_UART);
    // No hardware flow control
    uart_set_hw_flow(jdy_uart, false, false);
    // 8N1
    uart_set_format(jdy_uart, 8, 1, UART_PARITY_NONE);
    // Optionally set FIFO enabled/disabled; default OK.
    return true;
}

void jdy41_deinit(void) {
    // Reset pins to input to free them (optional)
    gpio_set_function(jdy_tx_pin, GPIO_FUNC_NULL);
    gpio_set_function(jdy_rx_pin, GPIO_FUNC_NULL);
}

// Write raw bytes (blocking)
int jdy41_write_raw(const char *buf, size_t len) {
    if (!buf || len == 0) return 0;
    return uart_write_blocking(jdy_uart, (const uint8_t *)buf, len);
}

// Write string (no automatic CRLF)
int jdy41_write_str(const char *s) {
    return jdy41_write_raw(s, strlen(s));
}

// Send an AT command with CRLF appended
int jdy41_send_cmd(const char *cmd) {
    if (!cmd) return -1;
    int n = jdy41_write_str(cmd);
    jdy41_write_str("\r\n");
    return n;
}

// Read one line (strips CR, stops at LF). Returns bytes read (0 = timeout)
// timeout_ms: how long to wait for a full line
int jdy41_read_line(char *out_buf, size_t maxlen, uint32_t timeout_ms) {
    if (!out_buf || maxlen == 0) return -1;
    size_t idx = 0;
    uint64_t start_us = time_us_64();
    uint64_t tout_us = (uint64_t)timeout_ms * 1000ULL;

    while (time_us_64() - start_us < tout_us) {
        if (uart_is_readable(jdy_uart)) {
            int c = uart_getc(jdy_uart); // returns -1 if none
            if (c == -1) continue;
            if (c == '\r') continue; // ignore CR
            if (c == '\n') {
                if (idx == 0) continue; // skip blank lines
                out_buf[idx] = '\0';
                return (int)idx;
            }
            if (idx < maxlen - 1) {
                out_buf[idx++] = (char)c;
            }
        }
    }
    // timeout: terminate if we have partial data
    if (idx > 0) {
        out_buf[idx] = '\0';
        return (int)idx;
    }
    return 0;
}

// Send command and wait for a single-line response (or until timeout)
// Returns bytes read into resp_buf (0 = timeout / no data)
int jdy41_send_cmd_wait(const char *cmd, char *resp_buf, size_t resp_buf_len, uint32_t timeout_ms) {
    if (!cmd || !resp_buf || resp_buf_len == 0) return -1;
    // Flush any pending input first (simple drain)
    while (uart_is_readable(jdy_uart)) uart_getc(jdy_uart);

    jdy41_send_cmd(cmd);
    int r = jdy41_read_line(resp_buf, resp_buf_len, timeout_ms);
    return r;
}

// Convenience: send AT and expect "OK" in reply within timeout_ms
bool jdy41_ping(uint32_t timeout_ms) {
    char buf[JDY41_RX_BUF_SIZE];
    int r = jdy41_send_cmd_wait("AT", buf, sizeof(buf), timeout_ms);
    if (r > 0 && strstr(buf, "OK") != NULL) return true;
    return false;
}

// Example usage in main
#ifdef JDY41_EXAMPLE_MAIN
int main() {
    stdio_init_all(); // for printf over USB
    sleep_ms(500);

    jdy41_init(JDY41_TX_PIN, JDY41_RX_PIN, JDY41_BAUD);

    printf("Pinging JDY-41...\n");
    if (jdy41_ping(1000)) {
        printf("JDY-41 responded to AT.\n");
    } else {
        printf("No response or timeout.\n");
    }

    // Example: send an arbitrary AT command and print one-line response
    char resp[JDY41_RX_BUF_SIZE];
    jdy41_send_cmd_wait("AT+VERSION", resp, sizeof(resp), 1000);
    printf("Response: %s\n", resp);

    while (true) {
        sleep_ms(1000);
    }
    return 0;
}
#endif
```

Notes and suggestions:
- The library is AT-generic. Use JDY-41-specific AT strings (module manual) for operations such as setting name, baud, advertising, or data mode.
- Adjust TX/RX pin defines if you use UART1 or other GPIO pins.
- Timeouts and buffer sizes are conservative — increase JDY41_RX_BUF_SIZE if you expect long responses.
- For more advanced behavior (async notifications, multi-line parsing, or binary framing) adapt the read loop to accumulate until your expected token(s).

