["Below is a compact, working example you can drop into a Unity project to fetch a Facebook video's direct source URL via the Graph API and download the file to Application.persistentDataPath. It assumes you already have a valid Facebook access token with the appropriate permission (e.g., user_videos for a user-owned video or a page access token for page videos).

Usage overview:
- Attach the FBVideoDownloader component to a GameObject.
- Hook up UI InputFields for video ID and access token, a Button to start, and a Text to show status/progress.
- Click the button to fetch the video "source" URL from the Graph API and download the .mp4 file.

Notes and requirements:
- You must have a valid access token and the right permissions (user_videos or page token). Apps typically need review for these scopes if used by other people.
- Respect copyright and Facebook policies — only download videos you are authorized to access.

C# script (one file):

using System.Collections;
using System.IO;
using UnityEngine;
using UnityEngine.Networking;
using UnityEngine.UI;

public class FBVideoDownloader : MonoBehaviour
{
    [Header("UI")]
    public InputField videoIdInput;        // enter the Facebook video ID
    public InputField accessTokenInput;    // enter a valid FB access token
    public Button downloadButton;
    public Text statusText;

    void Start()
    {
        if (downloadButton != null) downloadButton.onClick.AddListener(OnDownloadClicked);
    }

    void OnDownloadClicked()
    {
        string vid = videoIdInput != null ? videoIdInput.text.Trim() : "";
        string token = accessTokenInput != null ? accessTokenInput.text.Trim() : "";
        if (string.IsNullOrEmpty(vid) || string.IsNullOrEmpty(token))
        {
            SetStatus("Please provide video ID and access token.");
            return;
        }
        StartCoroutine(GetVideoSourceAndDownload(vid, token));
    }

    IEnumerator GetVideoSourceAndDownload(string videoId, string accessToken)
    {
        SetStatus("Fetching video info...");

        // Graph API request to get the video 'source' field
        string graphUrl = $"https://graph.facebook.com/{videoId}?fields=source&access_token={UnityWebRequest.EscapeURL(accessToken)}";
        using (UnityWebRequest uwr = UnityWebRequest.Get(graphUrl))
        {
            yield return uwr.SendWebRequest();

            if (uwr.result != UnityWebRequest.Result.Success)
            {
                SetStatus($"Graph API error: {uwr.error}");
                yield break;
            }

            string json = uwr.downloadHandler.text;
            VideoSourceResponse resp = null;
            try
            {
                resp = JsonUtility.FromJson<VideoSourceResponse>(json);
            }
            catch {
                SetStatus("Failed to parse Graph API response.");
                yield break;
            }

            if (resp == null || string.IsNullOrEmpty(resp.source))
            {
                SetStatus("No 'source' field returned. Make sure the token has permission and the video is accessible.");
                yield break;
            }

            string sourceUrl = resp.source;
            SetStatus("Downloading video...");
            string filename = $"fb_video_{videoId}.mp4";
            string path = Path.Combine(Application.persistentDataPath, filename);
            yield return StartCoroutine(DownloadToFile(sourceUrl, path));
        }
    }

    IEnumerator DownloadToFile(string url, string filePath)
    {
        // Use DownloadHandlerFile to stream directly to disk
        using (UnityWebRequest uwr = new UnityWebRequest(url, UnityWebRequest.kHttpVerbGET))
        {
            uwr.downloadHandler = new DownloadHandlerFile(filePath);
            uwr.SendWebRequest();

            while (!uwr.isDone)
            {
                SetStatus($"Downloading... {uwr.downloadProgress * 100f:F1}%");
                yield return null;
            }

            if (uwr.result != UnityWebRequest.Result.Success)
            {
                // Clean up partial file if exists
                if (File.Exists(filePath)) File.Delete(filePath);
                SetStatus($"Download failed: {uwr.error}");
                yield break;
            }

            SetStatus($"Download complete: {filePath}");
        }
    }

    void SetStatus(string message)
    {
        if (statusText != null) statusText.text = message;
        Debug.Log(message);
    }

    [System.Serializable]
    private class VideoSourceResponse
    {
        public string source;
    }
}

Final tips:
- If you want user-friendly login flows, integrate the Facebook SDK for Unity and obtain an access token through FB.Login rather than asking users to paste tokens.
- For robustness, handle token expiration and Graph API errors (rate limits, permissions denied).
- Test with videos you control first to ensure permissions are correct.

