1) VideoDownloadManager.cs

using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.Networking;
using UnityEngine.UI;
using UnityEngine.SceneManagement;

[Serializable]
public class ResolutionUrl {
    public string label; // e.g. "720p"
    public string url;   // direct download URL for this resolution
}

public class VideoDownloadManager : MonoBehaviour {
    public Dropdown resolutionDropdown;
    public Button downloadButton;
    public Text statusText;
    public List<ResolutionUrl> sources = new List<ResolutionUrl>();
    public string fileNamePrefix = "fbvideo_";

    void Start() {
        PopulateDropdown();
        downloadButton.onClick.AddListener(OnDownloadClicked);
    }

    void PopulateDropdown() {
        resolutionDropdown.ClearOptions();
        var options = new List<string>();
        foreach (var s in sources) options.Add(s.label);
        resolutionDropdown.AddOptions(options);
    }

    void OnDownloadClicked() {
        int idx = resolutionDropdown.value;
        if (idx < 0 || idx >= sources.Count) {
            statusText.text = "Please select a resolution.";
            return;
        }
        StartCoroutine(DownloadVideoCoroutine(sources[idx].url, sources[idx].label));
    }

    IEnumerator DownloadVideoCoroutine(string url, string label) {
        statusText.text = "Preparing...";
        string dir = Path.Combine(Application.persistentDataPath, "Videos");
        if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);
        string filename = fileNamePrefix + label + "_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".mp4";
        string filepath = Path.Combine(dir, filename);

        using (var uwr = UnityWebRequest.Get(url)) {
            uwr.downloadHandler = new DownloadHandlerFile(filepath);
            var op = uwr.SendWebRequest();
            while (!op.isDone) {
                statusText.text = $"Downloading {label}: {uwr.downloadProgress * 100:F1}%";
                yield return null;
            }

            if (uwr.result == UnityWebRequest.Result.ConnectionError || uwr.result == UnityWebRequest.Result.ProtocolError) {
                statusText.text = "Download failed: " + uwr.error;
                if (File.Exists(filepath)) File.Delete(filepath);
            } else {
                statusText.text = "Download complete: " + filename;
                yield return new WaitForSeconds(0.4f);
                SceneManager.LoadScene("VideoListScene");
            }
        }
    }
}

2) VideoListManager.cs

using System.IO;
using UnityEngine;
using UnityEngine.SceneManagement;

public class VideoListManager : MonoBehaviour {
    public Transform contentParent; // set to ScrollView content
    public GameObject itemPrefab;    // prefab that has VideoItemUI

    void Start() {
        RefreshList();
    }

    public void RefreshList() {
        foreach (Transform t in contentParent) Destroy(t.gameObject);
        string dir = Path.Combine(Application.persistentDataPath, "Videos");
        if (!Directory.Exists(dir)) return;
        var files = Directory.GetFiles(dir, "*.mp4");
        foreach (var f in files) {
            var go = Instantiate(itemPrefab, contentParent);
            var ui = go.GetComponent<VideoItemUI>();
            ui.Setup(f, this);
        }
    }

    public void BackToMain() {
        SceneManager.LoadScene("MainScene");
    }
}

3) VideoItemUI.cs

using System.IO;
using UnityEngine;
using UnityEngine.UI;

public class VideoItemUI : MonoBehaviour {
    public Text fileNameText;
    public Button deleteButton;
    public Button shareButton;

    string path;
    VideoListManager parentManager;

    public void Setup(string filepath, VideoListManager parent) {
        path = filepath;
        parentManager = parent;
        fileNameText.text = Path.GetFileName(filepath);
        deleteButton.onClick.AddListener(OnDelete);
        shareButton.onClick.AddListener(OnShare);
    }

    void OnDelete() {
        if (File.Exists(path)) File.Delete(path);
        Destroy(gameObject);
    }

    void OnShare() {
#if UNITY_ANDROID && !UNITY_EDITOR
        try {
            AndroidJavaClass intentClass = new AndroidJavaClass("android.content.Intent");
            AndroidJavaObject intentObject = new AndroidJavaObject("android.content.Intent");
            string ACTION_SEND = intentClass.GetStatic<string>("ACTION_SEND");
            intentObject.Call<AndroidJavaObject>("setAction", ACTION_SEND);

            AndroidJavaClass uriClass = new AndroidJavaClass("android.net.Uri");
            AndroidJavaObject fileObj = new AndroidJavaObject("java.io.File", path);
            AndroidJavaObject uri = uriClass.CallStatic<AndroidJavaObject>("fromFile", fileObj);

            string EXTRA_STREAM = intentClass.GetStatic<string>("EXTRA_STREAM");
            intentObject.Call<AndroidJavaObject>("putExtra", EXTRA_STREAM, uri);
            intentObject.Call<AndroidJavaObject>("setType", "video/*");

            AndroidJavaClass unity = new AndroidJavaClass("com.unity3d.player.UnityPlayer");
            AndroidJavaObject currentActivity = unity.GetStatic<AndroidJavaObject>("currentActivity");
            currentActivity.Call("startActivity", intentObject);
        } catch (System.Exception e) {
            Debug.Log("Share failed: " + e);
        }
#else
        // Editor / fallback: reveal file location
#if UNITY_EDITOR
        UnityEditor.EditorUtility.RevealInFinder(path);
#else
        Debug.Log("Share not implemented on this platform. Path: " + path);
#endif
#endif
    }
}

Important implementation notes and limitations:
- This code assumes you already have direct downloadable URLs (one per resolution). Obtaining those URLs from Facebook requires using the Graph API / SDK with proper permissions and tokens — integrate that part separately and populate the "sources" list programmatically or in the Inspector.
- DownloadHandlerFile writes directly to disk (efficient). On Android this writes into app-private storage (Application.persistentDataPath) — no extra runtime permission needed for app-private storage.
- The Android share implementation uses an intent with a file:// URI; on newer Android versions you may need to use FileProvider to share files securely. The provided snippet is a simple starting point.
- For production you should add error handling, UI polish, permission checks, and respect platform/store policies and Facebook terms before distributing an app that downloads content.

