using UnityEngine;
using UnityEngine.UI;
using UnityEngine.Networking;
using System.Collections;
using System.Collections.Generic;
using System.IO;

public class FacebookVideoDownloaderUI : MonoBehaviour
{
    [Header("Resolution URLs (direct video file URLs)")]
    public string url720p;
    public string url1080p;
    public string url2k;    // e.g. 1440p
    public string url4k;

    [Header("UI References")]
    public Dropdown resolutionDropdown; // Populate at runtime
    public Button downloadButton;
    public Text downloadStatusText;

    [Header("Downloaded videos page")]
    public GameObject videosPanel; // container panel to show after download
    public Transform videosListContent; // parent for items
    public GameObject videoListItemPrefab; // prefab with: Text nameText, Button deleteButton, Button shareButton

    string saveFolder;
    Dictionary<string, string> availableResolutions = new Dictionary<string, string>();

    void Start()
    {
        saveFolder = Path.Combine(Application.persistentDataPath, "Videos");
        if (!Directory.Exists(saveFolder)) Directory.CreateDirectory(saveFolder);

        // Build available resolutions map from public fields (only add non-empty URLs)
        AddIfValid("720p", url720p);
        AddIfValid("1080p", url1080p);
        AddIfValid("2K", url2k);
        AddIfValid("4K", url4k);

        PopulateResolutionDropdown();

        downloadButton.onClick.RemoveAllListeners();
        downloadButton.onClick.AddListener(OnDownloadButtonClicked);

        // Initially hide videos panel until after download (or you can show it always)
        if (videosPanel) videosPanel.SetActive(false);
    }

    void AddIfValid(string label, string url)
    {
        if (!string.IsNullOrEmpty(url))
            availableResolutions[label] = url;
    }

    void PopulateResolutionDropdown()
    {
        resolutionDropdown.ClearOptions();
        List<string> options = new List<string>(availableResolutions.Keys);
        if (options.Count == 0)
        {
            options.Add("No available resolutions");
            resolutionDropdown.interactable = false;
            downloadButton.interactable = false;
        }
        else
        {
            resolutionDropdown.interactable = true;
            downloadButton.interactable = true;
        }
        resolutionDropdown.AddOptions(options);
    }

    void OnDownloadButtonClicked()
    {
        if (availableResolutions.Count == 0)
        {
            SetStatus("No resolution URLs provided.");
            return;
        }

        string selected = resolutionDropdown.options[resolutionDropdown.value].text;
        if (!availableResolutions.ContainsKey(selected))
        {
            SetStatus("Selected resolution not available.");
            return;
        }

        string url = availableResolutions[selected];
        string ext = Path.GetExtension(url);
        if (string.IsNullOrEmpty(ext)) ext = ".mp4";
        string fileName = string.Format("video_{0}_{1}{2}", System.DateTime.Now.ToString("yyyyMMdd_HHmmss"), selected, ext);
        string savePath = Path.Combine(saveFolder, fileName);

        StartCoroutine(DownloadVideoCoroutine(url, savePath));
    }

    IEnumerator DownloadVideoCoroutine(string url, string savePath)
    {
        SetStatus("Starting download...");

        using (UnityWebRequest uwr = UnityWebRequest.Get(url))
        {
            uwr.downloadHandler = new DownloadHandlerFile(savePath);
            uwr.timeout = 120; // seconds, increase for large files

            yield return uwr.SendWebRequest();

#if UNITY_2020_1_OR_NEWER
            if (uwr.result == UnityWebRequest.Result.ConnectionError || uwr.result == UnityWebRequest.Result.ProtocolError)
#else
            if (uwr.isNetworkError || uwr.isHttpError)
#endif
            {
                SetStatus("Download error: " + uwr.error);
                // If file exists but is incomplete, try delete
                if (File.Exists(savePath)) File.Delete(savePath);
            }
            else
            {
                SetStatus("Download complete: " + Path.GetFileName(savePath));
                // Show videos page and refresh list
                if (videosPanel) videosPanel.SetActive(true);
                RefreshVideoList();
            }
        }
    }

    void SetStatus(string text)
    {
        if (downloadStatusText) downloadStatusText.text = text;
        else Debug.Log(text);
    }

    void RefreshVideoList()
    {
        // Clear current list
        foreach (Transform child in videosListContent)
            Destroy(child.gameObject);

        if (!Directory.Exists(saveFolder)) return;

        string[] files = Directory.GetFiles(saveFolder);
        System.Array.Sort(files); // sort by name/time if desired

        foreach (string file in files)
        {
            // Limit to common video extensions
            string ext = Path.GetExtension(file).ToLower();
            if (ext != ".mp4" && ext != ".mov" && ext != ".m4v" && ext != ".webm") continue;

            GameObject item = Instantiate(videoListItemPrefab, videosListContent);

            // Expect prefab has these child components; adapt names to your prefab
            Text nameText = item.transform.Find("NameText").GetComponent<Text>();
            Button deleteBtn = item.transform.Find("DeleteButton").GetComponent<Button>();
            Button shareBtn = item.transform.Find("ShareButton").GetComponent<Button>();

            string fileName = Path.GetFileName(file);
            nameText.text = fileName;

            // Remove previous listeners then add
            deleteBtn.onClick.RemoveAllListeners();
            deleteBtn.onClick.AddListener(() => { DeleteVideo(file); });

            shareBtn.onClick.RemoveAllListeners();
            shareBtn.onClick.AddListener(() => { ShareVideo(file); });
        }
    }

    void DeleteVideo(string path)
    {
        if (File.Exists(path))
        {
            File.Delete(path);
            SetStatus("Deleted " + Path.GetFileName(path));
            RefreshVideoList();
        }
        else
        {
            SetStatus("File not found.");
            RefreshVideoList();
        }
    }

    void ShareVideo(string path)
    {
        // Simple fallback: attempt to open the file. On many platforms this will open the associated app.
        // For native share sheet on Android/iOS, use a plugin (e.g., NativeShare) or implement platform-specific code.
        if (File.Exists(path))
        {
            SetStatus("Opening " + Path.GetFileName(path));
            string url = "file://" + path;
            Application.OpenURL(url);
        }
        else
        {
            SetStatus("File not found for sharing.");
        }
    }
}

