Notes before using:
- You need a valid access token and appropriate permissions for the Graph API.
- Facebook Graph API video responses include a `format` array with sources at different resolutions; the script picks the closest match.
- For sharing on Android the script includes a simple native Intent implementation; on iOS you’ll need a native plugin or Unity Social API.

1) FacebookVideoDownloader.cs (attach to your main UI GameObject)
```csharp
using System;
using System.IO;
using System.Linq;
using System.Collections;
using UnityEngine;
using UnityEngine.Networking;
using UnityEngine.UI;

[Serializable]
class VideoFormat { public string source; public int height; public int width; }
[Serializable]
class VideoInfo { public string id; public string source; public VideoFormat[] format; }

public class FacebookVideoDownloader : MonoBehaviour
{
    [Header("Facebook")]
    public string accessToken; // set in Inspector

    [Header("UI")]
    public InputField videoIdInput; // allow user to paste video ID or URL
    public Dropdown resolutionDropdown; // options: 720, 1080, 1440, 2160
    public Button downloadButton;
    public GameObject loadingIndicator;

    [Header("Download/List")]
    public VideoListManager videoListManager; // reference to manager that shows downloaded videos

    string downloadFolder => Path.Combine(Application.persistentDataPath, "FBVideos");

    void Start()
    {
        // Populate dropdown
        resolutionDropdown.ClearOptions();
        resolutionDropdown.AddOptions(new System.Collections.Generic.List<string> { "720", "1080", "1440", "2160" });

        downloadButton.onClick.AddListener(OnDownloadClicked);
        if (!Directory.Exists(downloadFolder)) Directory.CreateDirectory(downloadFolder);
    }

    void OnDownloadClicked()
    {
        var raw = videoIdInput.text.Trim();
        if (string.IsNullOrEmpty(raw)) { Debug.LogWarning("Enter a video ID or URL"); return; }

        string videoId = ExtractVideoIdFromInput(raw);
        int targetHeight = int.Parse(resolutionDropdown.options[resolutionDropdown.value].text);
        StartCoroutine(DownloadVideoFlow(videoId, targetHeight));
    }

    string ExtractVideoIdFromInput(string input)
    {
        // Very simple: if input contains "facebook.com" try to extract the last path segment, otherwise assume it's the ID.
        try
        {
            if (input.Contains("facebook.com"))
            {
                var uri = new Uri(input);
                var seg = uri.Segments.Last().Trim('/');
                return seg;
            }
        }
        catch { }
        return input; // fallback
    }

    IEnumerator DownloadVideoFlow(string videoId, int targetHeight)
    {
        loadingIndicator?.SetActive(true);

        // 1) Query Graph API for formats
        string url = $"https://graph.facebook.com/{videoId}?fields=source,format&access_token={accessToken}";
        using (UnityWebRequest req = UnityWebRequest.Get(url))
        {
            yield return req.SendWebRequest();
            if (req.result != UnityWebRequest.Result.Success)
            {
                Debug.LogError("Graph API request failed: " + req.error);
                loadingIndicator?.SetActive(false);
                yield break;
            }

            string json = req.downloadHandler.text;
            VideoInfo info = null;
            try { info = JsonUtility.FromJson<VideoInfo>(json); }
            catch { Debug.LogWarning("JSON parse with JsonUtility failed; trying manual parse"); }

            // If JsonUtility didn't parse format array correctly, do a manual lightweight parse
            if (info == null || (info.format == null || info.format.Length == 0))
            {
                // Attempt to parse the format array using simple search (best-effort)
                // Search for occurrences of "\"source\":\"...mp4\"" and nearby heights
                System.Collections.Generic.List<VideoFormat> fmts = new System.Collections.Generic.List<VideoFormat>();
                var tokens = json.Split(new[] { '"' }, StringSplitOptions.RemoveEmptyEntries);
                for (int i = 0; i < tokens.Length - 1; i++)
                {
                    if (tokens[i] == "source" && tokens[i + 1].StartsWith(":")) continue; // skip
                    if (tokens[i] == "source")
                    {
                        string candidate = tokens[i + 2]; // best-effort
                        if (candidate.StartsWith(":")) candidate = candidate.Substring(1);
                        if (candidate.Contains("http"))
                        {
                            fmts.Add(new VideoFormat { source = candidate, height = 0, width = 0 });
                        }
                    }
                }
                info = new VideoInfo { id = videoId, source = null, format = fmts.ToArray() };
            }

            // 2) Pick best format for requested height
            string chosenUrl = null;
            if (info.format != null && info.format.Length > 0)
            {
                // prefer exact or nearest height >= target, fallback to largest available
                VideoFormat best = null;
                foreach (var f in info.format)
                {
                    if (string.IsNullOrEmpty(f.source)) continue;
                    if (best == null) { best = f; continue; }
                    if (f.height == targetHeight) { best = f; break; }
                    // if f.height is closer to target than best
                    if (Math.Abs(f.height - targetHeight) < Math.Abs(best.height - targetHeight)) best = f;
                }
                chosenUrl = best?.source ?? info.source;
            }
            else
            {
                chosenUrl = info.source;
            }

            if (string.IsNullOrEmpty(chosenUrl))
            {
                Debug.LogError("No downloadable source found in Graph API response.");
                loadingIndicator?.SetActive(false);
                yield break;
            }

            // 3) Download to file using DownloadHandlerFile
            string safeFileName = SanitizeFileName($"fb_{videoId}_{targetHeight}.mp4");
            string fullPath = Path.Combine(downloadFolder, safeFileName);
            using (UnityWebRequest dl = UnityWebRequest.Get(chosenUrl))
            {
                dl.downloadHandler = new DownloadHandlerFile(fullPath);
                yield return dl.SendWebRequest();
                if (dl.result != UnityWebRequest.Result.Success)
                {
                    Debug.LogError("Download failed: " + dl.error);
                    loadingIndicator?.SetActive(false);
                    yield break;
                }
            }

            // 4) Add to list manager
            videoListManager?.AddDownloadedVideo(fullPath, videoId);
            loadingIndicator?.SetActive(false);
        }
    }

    string SanitizeFileName(string name)
    {
        foreach (char c in Path.GetInvalidFileNameChars()) name = name.Replace(c, '_');
        return name;
    }
}
```

