4) AndroidShare.cs (simple Android share implementation)
```csharp
#if UNITY_ANDROID && !UNITY_EDITOR
using UnityEngine;
public static class AndroidShare
{
    public static void ShareFile(string filePath, string text)
    {
        try
        {
            AndroidJavaClass intentClass = new AndroidJavaClass("android.content.Intent");
            AndroidJavaObject intent = new AndroidJavaObject("android.content.Intent");
            intent.Call<AndroidJavaObject>("setAction", intentClass.GetStatic<string>("ACTION_SEND"));

            AndroidJavaObject fileObj = new AndroidJavaObject("java.io.File", filePath);
            AndroidJavaClass uriClass = new AndroidJavaClass("android.net.Uri");
            AndroidJavaObject uri = uriClass.CallStatic<AndroidJavaObject>("fromFile", fileObj);

            intent.Call<AndroidJavaObject>("putExtra", intentClass.GetStatic<string>("EXTRA_STREAM"), uri);
            intent.Call<AndroidJavaObject>("putExtra", intentClass.GetStatic<string>("EXTRA_TEXT"), text);
            intent.Call<AndroidJavaObject>("setType", "video/*");

            AndroidJavaClass unity = new AndroidJavaClass("com.unity3d.player.UnityPlayer");
            AndroidJavaObject currentActivity = unity.GetStatic<AndroidJavaObject>("currentActivity");

            AndroidJavaObject chooser = intentClass.CallStatic<AndroidJavaObject>("createChooser", intent, "Share video");
            currentActivity.Call("startActivity", chooser);
        }
        catch (System.Exception e) { Debug.LogWarning("Android share failed: " + e.Message); }
    }
}
#endif
```

