Notes before using the code:
- You must implement GetDirectVideoUrlForResolutionAsync(videoId, resolution) using the Facebook SDK / Graph API to return a downloadable .mp4 URL for the chosen resolution.
- The Share implementation includes an Android Intent example; for other platforms you can adapt as needed.

Files:
1) FBVideoManager.cs — main manager
2) VideoItemUI.cs — UI item script (attach to your video list item prefab)

--- FBVideoManager.cs ---
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.Networking;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;

public class FBVideoManager : MonoBehaviour
{
    [Header("UI")]
    public InputField videoIdInput;          // Enter Facebook video ID or URL placeholder
    public Dropdown resolutionDropdown;      // Populate with: 720p, 1080p, 2K, 4K
    public Button downloadButton;
    public Transform listContent;            // Parent for items
    public GameObject videoItemPrefab;       // Prefab with VideoItemUI attached

    private List<DownloadedVideo> downloadedVideos = new List<DownloadedVideo>();

    void Start()
    {
        // Setup dropdown options if not set in editor
        if (resolutionDropdown != null && resolutionDropdown.options.Count == 0)
        {
            resolutionDropdown.options.Add(new Dropdown.OptionData("720p"));
            resolutionDropdown.options.Add(new Dropdown.OptionData("1080p"));
            resolutionDropdown.options.Add(new Dropdown.OptionData("2K"));
            resolutionDropdown.options.Add(new Dropdown.OptionData("4K"));
        }

        if (downloadButton != null)
            downloadButton.onClick.AddListener(OnDownloadClicked);

        // Load previously downloaded list if you want (not implemented here)
    }

    public void OnDownloadClicked()
    {
        string videoIdOrInput = videoIdInput.text.Trim();
        string resolution = resolutionDropdown.options[resolutionDropdown.value].text;

        if (string.IsNullOrEmpty(videoIdOrInput))
        {
            Debug.LogWarning("Please enter a video ID or URL.");
            return;
        }

        StartCoroutine(DownloadVideoCoroutine(videoIdOrInput, resolution));
    }

    private IEnumerator DownloadVideoCoroutine(string videoIdOrInput, string resolution)
    {
        // 1) Get a direct downloadable URL for the chosen resolution
        var task = GetDirectVideoUrlForResolutionAsync(videoIdOrInput, resolution);
        while (!task.IsCompleted) yield return null;
        string videoUrl = task.Result;

        if (string.IsNullOrEmpty(videoUrl))
        {
            Debug.LogError("Could not obtain direct video URL. Implement GetDirectVideoUrlForResolutionAsync using Facebook SDK / Graph API.");
            yield break;
        }

        // 2) Download the video via UnityWebRequest
        string fileName = MakeSafeFileName($"fb_{videoIdOrInput}_{resolution}") + ".mp4";
        string savePath = Path.Combine(Application.persistentDataPath, fileName);

        using (UnityWebRequest uwr = UnityWebRequest.Get(videoUrl))
        {
            uwr.downloadHandler = new DownloadHandlerBuffer();
            var asyncOp = uwr.SendWebRequest();
            while (!asyncOp.isDone) yield return null;

#if UNITY_2020_1_OR_NEWER
            if (uwr.result != UnityWebRequest.Result.Success)
#else
            if (uwr.isNetworkError || uwr.isHttpError)
#endif
            {
                Debug.LogError("Download failed: " + uwr.error);
                yield break;
            }

            byte[] bytes = uwr.downloadHandler.data;
            try
            {
                File.WriteAllBytes(savePath, bytes);
            }
            catch (System.Exception ex)
            {
                Debug.LogError("Failed to save file: " + ex.Message);
                yield break;
            }
        }

        // 3) Register the downloaded video and show in list
        var dv = new DownloadedVideo { id = System.Guid.NewGuid().ToString(), title = fileName, path = savePath };
        downloadedVideos.Add(dv);
        AddVideoItemToUI(dv);

        Debug.Log($"Downloaded and saved to: {savePath}");
    }

    // Adds an item to the UI list and wire up buttons
    private void AddVideoItemToUI(DownloadedVideo dv)
    {
        if (videoItemPrefab == null || listContent == null)
        {
            Debug.LogWarning("videoItemPrefab or listContent is not set.");
            return;
        }

        GameObject go = Instantiate(videoItemPrefab, listContent);
        VideoItemUI ui = go.GetComponent<VideoItemUI>();
        if (ui == null)
        {
            Debug.LogError("videoItemPrefab must have a VideoItemUI component.");
            return;
        }

        ui.Setup(dv, OnDeleteClicked, OnShareClicked);
    }

    private void OnDeleteClicked(DownloadedVideo dv, VideoItemUI ui)
    {
        // Delete file
        if (File.Exists(dv.path))
        {
            try { File.Delete(dv.path); }
            catch (System.Exception ex) { Debug.LogError("Delete failed: " + ex.Message); }
        }

        downloadedVideos.Remove(dv);
        if (ui != null) Destroy(ui.gameObject);
    }

    private void OnShareClicked(DownloadedVideo dv)
    {
        if (!File.Exists(dv.path))
        {
            Debug.LogWarning("File not found: " + dv.path);
            return;
        }

        ShareFile(dv.path, dv.title);
    }

    // Platform-specific share (simple Android example)
    private void ShareFile(string filePath, string title)
    {
#if UNITY_ANDROID && !UNITY_EDITOR
        try
        {
            AndroidJavaClass intentClass = new AndroidJavaClass("android.content.Intent");
            AndroidJavaObject intentObject = new AndroidJavaObject("android.content.Intent");
            intentObject.Call<AndroidJavaObject>("setAction", intentClass.GetStatic<string>("ACTION_SEND"));

            AndroidJavaClass uriClass = new AndroidJavaClass("android.net.Uri");
            AndroidJavaObject fileObj = new AndroidJavaObject("java.io.File", filePath);
            AndroidJavaObject uri = uriClass.CallStatic<AndroidJavaObject>("fromFile", fileObj);

            intentObject.Call<AndroidJavaObject>("putExtra", intentClass.GetStatic<string>("EXTRA_STREAM"), uri);
            intentObject.Call<AndroidJavaObject>("setType", "video/mp4");

            AndroidJavaClass unity = new AndroidJavaClass("com.unity3d.player.UnityPlayer");
            AndroidJavaObject currentActivity = unity.GetStatic<AndroidJavaObject>("currentActivity");
            AndroidJavaObject chooser = intentClass.CallStatic<AndroidJavaObject>("createChooser", intentObject, title);
            currentActivity.Call("startActivity", chooser);
        }
        catch (System.Exception ex)
        {
            Debug.LogError("Android share failed: " + ex.Message);
        }
#else
        // Fallback: open the folder containing the file or show path
        Debug.Log($"Share not implemented on this platform. File is at: {filePath}");
#endif
    }

    // Helper to create safe filenames
    private string MakeSafeFileName(string name)
    {
        foreach (char c in Path.GetInvalidFileNameChars()) name = name.Replace(c, '_');
        return name;
    }

    // Placeholder: you must implement this to return a direct video file URL for the requested resolution.
    // Use Facebook SDK / Graph API to query the video object and select the appropriate source URL.
    private async Task<string> GetDirectVideoUrlForResolutionAsync(string videoIdOrInput, string resolution)
    {
        // Example:
        // - Use FB SDK to fetch video object and its available sources
        // - Select URL that best matches the requested resolution
        // - Return the direct MP4 URL

        await Task.Yield(); // placeholder to keep method async
        return null; // implement and return the actual URL
    }

    // Simple data holder
    public class DownloadedVideo
    {
        public string id;
        public string title;
        public string path;
    }
}

--- VideoItemUI.cs ---
using UnityEngine;
using UnityEngine.UI;

public class VideoItemUI : MonoBehaviour
{
    public Text titleText;
    public Button playButton;   // optional: you could implement in-app playback
    public Button deleteButton;
    public Button shareButton;

    private FBVideoManager.DownloadedVideo dv;
    private System.Action<FBVideoManager.DownloadedVideo, VideoItemUI> onDelete;
    private System.Action<FBVideoManager.DownloadedVideo> onShare;

    public void Setup(FBVideoManager.DownloadedVideo video, System.Action<FBVideoManager.DownloadedVideo, VideoItemUI> deleteCb, System.Action<FBVideoManager.DownloadedVideo> shareCb)
    {
        dv = video;
        onDelete = deleteCb;
        onShare = shareCb;

        if (titleText != null) titleText.text = video.title;

        if (deleteButton != null)
        {
            deleteButton.onClick.RemoveAllListeners();
            deleteButton.onClick.AddListener(() => onDelete?.Invoke(dv, this));
        }

        if (shareButton != null)
        {
            shareButton.onClick.RemoveAllListeners();
            shareButton.onClick.AddListener(() => onShare?.Invoke(dv));
        }

        if (playButton != null)
        {
            // Optional: wire play to an in-app video player (not implemented here)
            playButton.onClick.RemoveAllListeners();
            playButton.onClick.AddListener(() => Debug.Log("Play not implemented: " + dv.path));
        }
    }
}

