predicted_preference:
["Here’s a simple, complete example that detects the user’s browser name and version, formats the output as

"Browser name": "Browser version", "date"

and appends that string as a new row in a table when the user clicks a button.

Put this HTML in your page (or integrate the relevant parts into your existing HTML):

<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Browser Version Table</title>
  <style>
    table { border-collapse: collapse; width: 100%; max-width: 700px; }
    th, td { border: 1px solid #ccc; padding: 6px 8px; }
    th { background: #f2f2f2; }
  </style>
</head>
<body>
  <button id="checkBtn">Get browser info</button>

  <table id="results">
    <thead>
      <tr>
        <th>Browser</th>
        <th>Version</th>
        <th>Date</th>
        <th>Output</th>
      </tr>
    </thead>
    <tbody></tbody>
  </table>

  <script>
    function getBrowserInfo() {
      // Prefer newer userAgentData when available
      if (navigator.userAgentData && navigator.userAgentData.brands) {
        const brands = navigator.userAgentData.brands;
        // prefer a meaningful brand (avoid generic "Chromium"/"Not A Brand")
        const choice = brands.find(b => b.brand && b.brand !== 'Chromium' && b.brand !== 'Not A Brand') || brands[0];
        return { name: choice.brand || 'Unknown', version: choice.version || '' };
      }

      // Fallback: parse navigator.userAgent
      const ua = navigator.userAgent;
      let name = 'Unknown', version = '';

      if (/Edg\/([\d.]+)/.test(ua)) { name = 'Edge'; version = RegExp.$1; }
      else if (/OPR\/([\d.]+)/.test(ua)) { name = 'Opera'; version = RegExp.$1; }
      else if (/Chrome\/([\d.]+)/.test(ua)) { name = 'Chrome'; version = RegExp.$1; }
      else if (/Firefox\/([\d.]+)/.test(ua)) { name = 'Firefox'; version = RegExp.$1; }
      else if (/Version\/([\d.]+).*Safari/.test(ua)) { name = 'Safari'; version = RegExp.$1; }
      else if (/MSIE\s([\d.]+)/.test(ua)) { name = 'IE'; version = RegExp.$1; }
      else if (/Trident.*rv:([\d.]+)/.test(ua)) { name = 'IE'; version = RegExp.$1; }

      return { name, version };
    }

    document.getElementById('checkBtn').addEventListener('click', function () {
      const info = getBrowserInfo();
      const date = new Date().toLocaleString();
      // required output format
      const output = `"${info.name}": "${info.version}", "${date}"`;

      const tbody = document.querySelector('#results tbody');
      const tr = document.createElement('tr');

      // add individual columns and the combined output column
      [info.name, info.version, date, output].forEach(text => {
        const td = document.createElement('td');
        td.textContent = text;
        tr.appendChild(td);
      });

      tbody.appendChild(tr);
    });
  </script>
</body>
</html>

Notes:
- navigator.userAgentData is more accurate and privacy-friendly when available; the script falls back to parsing navigator.userAgent for older browsers.
- Each click appends a new row with Browser, Version, Date, and the exactly formatted string in the "Output" column.
- You can remove columns you don’t need or style the table further as desired."]

